package archive

import (
	"archive/zip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/pkg/logger"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type CreateZipReq struct {
	InputFiles     string `json:"input_files" widget:"name:上传要打包的文件;type:files;accept:*/*;max_size:2000MB;max_count:200" validate:"required"`
	OutputFileName string `json:"output_file_name" widget:"name:输出 ZIP 文件名;type:input;render_default:workspace_files;placeholder:不用写 .zip"`
}

type CreateZipResp struct {
	OutputFile string `json:"output_file" widget:"name:ZIP 压缩包;type:files"`
	ZipInfo    string `json:"zip_info" widget:"name:打包信息;type:text_area"`
}

func CreateZip(ctx *app.Context, resp response.Response) error {
	var req CreateZipReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoCreateZip(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

func DoCreateZip(ctx *app.Context, req *CreateZipReq) (*CreateZipResp, error) {
	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)
	if len(inputFiles) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	outputDir := fs.GetTraceOutputDir()
	baseName := sanitizeArchiveName(strings.TrimSuffix(strings.TrimSpace(req.OutputFileName), ".zip"), "workspace_files")
	outputPath := filepath.Join(outputDir, baseName+".zip")

	outFile, err := os.Create(outputPath)
	if err != nil {
		return nil, fmt.Errorf("创建 ZIP 文件失败: %w", err)
	}
	defer outFile.Close()

	writer := zip.NewWriter(outFile)
	seenNames := make(map[string]int)
	var infos []string
	addedCount := 0
	var totalBytes int64
	for _, file := range inputFiles {
		if file == "" {
			continue
		}
		info, err := os.Stat(file)
		if err != nil {
			logger.Warnf(ctx, "[Archive/CreateZip] 读取文件失败 %s: %v", filepath.Base(file), err)
			infos = append(infos, fmt.Sprintf("跳过 %s: %v", filepath.Base(file), err))
			continue
		}
		if !info.Mode().IsRegular() {
			infos = append(infos, fmt.Sprintf("跳过 %s: 不是普通文件", filepath.Base(file)))
			continue
		}
		entryName := uniqueArchiveName(sanitizeArchiveName(filepath.Base(file), "file"), seenNames)
		if err := addFileToZip(writer, file, entryName); err != nil {
			logger.Warnf(ctx, "[Archive/CreateZip] 添加文件失败 %s: %v", filepath.Base(file), err)
			infos = append(infos, fmt.Sprintf("失败 %s: %v", filepath.Base(file), err))
			continue
		}
		addedCount++
		totalBytes += info.Size()
		infos = append(infos, fmt.Sprintf("成功添加 %s -> %s", filepath.Base(file), entryName))
	}
	if err := writer.Close(); err != nil {
		return nil, fmt.Errorf("写入 ZIP 文件失败: %w", err)
	}
	if addedCount == 0 {
		_ = os.Remove(outputPath)
		return nil, fmt.Errorf("没有成功打包的文件\n%s", strings.Join(infos, "\n"))
	}

	outputFiles := fs.ResponseFiles([]string{outputPath})
	zipInfo := fmt.Sprintf("ZIP 打包完成\n输出文件: %s\n文件数: %d\n原始总大小: %.2f MB", filepath.Base(outputPath), addedCount, float64(totalBytes)/(1024*1024))
	if len(infos) > 0 {
		zipInfo += "\n\n详情:\n" + strings.Join(infos, "\n")
	}
	return &CreateZipResp{OutputFile: outputFiles, ZipInfo: zipInfo}, nil
}

func addFileToZip(writer *zip.Writer, filePath, entryName string) error {
	info, err := os.Stat(filePath)
	if err != nil {
		return err
	}
	input, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer input.Close()

	header, err := zip.FileInfoHeader(info)
	if err != nil {
		return err
	}
	header.Name = entryName
	header.Method = zip.Deflate
	entryWriter, err := writer.CreateHeader(header)
	if err != nil {
		return err
	}
	_, err = io.Copy(entryWriter, input)
	return err
}

var CreateZipTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "打包文件为 ZIP",
		Desc:     `把多个工作台文件打包成一个 ZIP 压缩包，适合导出多张图片、多份文档、批量处理结果或交付附件。`,
		Tags:     []string{"压缩包", "ZIP", "打包", "文件", "交付"},
		Request:  &CreateZipReq{},
		Response: &CreateZipResp{},
	},
}

func init() {
	packageContext.POST("create_zip.form", CreateZip, CreateZipTemplate)
}

package archive

import (
	"archive/zip"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/pkg/logger"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type ExtractArchiveReq struct {
	InputFiles string `json:"input_files" widget:"name:上传压缩包;type:files;accept:.zip,.tar,.tgz,.tar.gz,.tar.xz,.txz,.tar.bz2,.tbz2,application/zip,application/x-tar,*/*;max_size:2000MB;max_count:20" validate:"required"`
	MaxFiles   int    `json:"max_files" widget:"name:最多返回文件数;type:number;min:1;max:500;render_default:100" validate:"min=0,max=500"`
}

type ExtractArchiveResp struct {
	OutputFiles string `json:"output_files" widget:"name:解出的文件;type:files"`
	ExtractInfo string `json:"extract_info" widget:"name:解包信息;type:text_area"`
}

func ExtractArchive(ctx *app.Context, resp response.Response) error {
	var req ExtractArchiveReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoExtractArchive(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

func DoExtractArchive(ctx *app.Context, req *ExtractArchiveReq) (*ExtractArchiveResp, error) {
	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)
	if len(inputFiles) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	maxFiles := req.MaxFiles
	if maxFiles <= 0 {
		maxFiles = 100
	}
	if maxFiles > 500 {
		maxFiles = 500
	}

	outputDir := fs.GetTraceOutputDir()
	seen := make(map[string]int)
	var outputPaths []string
	var infos []string
	for _, path := range inputFiles {
		if path == "" {
			continue
		}
		if len(outputPaths) >= maxFiles {
			infos = append(infos, fmt.Sprintf("跳过 %s: 已达到返回上限 %d", filepath.Base(path), maxFiles))
			continue
		}
		kind := archiveKind(path)
		var added []string
		var err error
		switch kind {
		case "zip":
			added, err = extractZipArchive(path, outputDir, seen, maxFiles-len(outputPaths))
		case "tar":
			added, err = extractTarArchive(path, outputDir, seen, maxFiles-len(outputPaths))
		default:
			err = fmt.Errorf("暂不支持该压缩包格式")
		}
		if err != nil {
			logger.Warnf(ctx, "[Archive/ExtractArchive] 解包失败 %s: %v", filepath.Base(path), err)
			infos = append(infos, fmt.Sprintf("失败 %s: %v", filepath.Base(path), err))
			continue
		}
		outputPaths = append(outputPaths, added...)
		infos = append(infos, fmt.Sprintf("成功 %s: 返回 %d 个文件", filepath.Base(path), len(added)))
	}
	if len(outputPaths) == 0 {
		return nil, fmt.Errorf("没有成功解出的文件\n%s", strings.Join(infos, "\n"))
	}
	if len(outputPaths) >= maxFiles {
		infos = append(infos, fmt.Sprintf("注意：已达到最多返回文件数 %d，更多文件未返回到工作台", maxFiles))
	}
	return &ExtractArchiveResp{
		OutputFiles: fs.ResponseFiles(outputPaths),
		ExtractInfo: "压缩包解包完成\n" + strings.Join(infos, "\n"),
	}, nil
}

func extractZipArchive(path, outputDir string, seen map[string]int, limit int) ([]string, error) {
	reader, err := zip.OpenReader(path)
	if err != nil {
		return nil, err
	}
	defer reader.Close()

	prefix := archiveBaseName(path)
	var outputPaths []string
	for _, entry := range reader.File {
		if len(outputPaths) >= limit {
			break
		}
		if entry.FileInfo().IsDir() || strings.HasPrefix(entry.Name, "__MACOSX/") || strings.HasSuffix(strings.ToLower(entry.Name), ".ds_store") {
			continue
		}
		entryReader, err := entry.Open()
		if err != nil {
			return nil, err
		}
		outputName := flattenEntryName(prefix, entry.Name, seen)
		outputPath := filepath.Join(outputDir, outputName)
		if err := os.MkdirAll(filepath.Dir(outputPath), 0755); err != nil {
			entryReader.Close()
			return nil, err
		}
		outputFile, err := os.Create(outputPath)
		if err != nil {
			entryReader.Close()
			return nil, err
		}
		_, copyErr := outputFile.ReadFrom(entryReader)
		closeErr := outputFile.Close()
		entryReader.Close()
		if copyErr != nil {
			return nil, copyErr
		}
		if closeErr != nil {
			return nil, closeErr
		}
		outputPaths = append(outputPaths, outputPath)
	}
	return outputPaths, nil
}

func extractTarArchive(path, outputDir string, seen map[string]int, limit int) ([]string, error) {
	if err := ensureTar(); err != nil {
		return nil, err
	}
	tempDir, err := os.MkdirTemp(outputDir, "archive_extract_*")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(tempDir)

	out, err := exec.Command("tar", "-xf", path, "-C", tempDir).CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("tar 解包失败: %v\n%s", err, strings.TrimSpace(string(out)))
	}

	prefix := archiveBaseName(path)
	var outputPaths []string
	err = filepath.WalkDir(tempDir, func(current string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if len(outputPaths) >= limit || entry.IsDir() {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() {
			return nil
		}
		rel, err := filepath.Rel(tempDir, current)
		if err != nil {
			return err
		}
		outputName := flattenEntryName(prefix, rel, seen)
		outputPath := filepath.Join(outputDir, outputName)
		if err := copyRegularFile(current, outputPath); err != nil {
			return err
		}
		outputPaths = append(outputPaths, outputPath)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return outputPaths, nil
}

var ExtractArchiveTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "解出通用压缩包",
		Desc:     `安全平铺解出 ZIP、TAR、TAR.GZ、TGZ、TAR.XZ 等压缩包中的文件，自动跳过目录和常见系统垃圾文件，并限制返回文件数量，适合处理用户上传资料包。`,
		Tags:     []string{"压缩包", "解包", "ZIP", "TAR", "资料包"},
		Request:  &ExtractArchiveReq{},
		Response: &ExtractArchiveResp{},
	},
}

func init() {
	packageContext.POST("extract.form", ExtractArchive, ExtractArchiveTemplate)
}

package archive

import (
	"archive/zip"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func archiveKind(path string) string {
	name := strings.ToLower(filepath.Base(path))
	switch {
	case strings.HasSuffix(name, ".zip"):
		return "zip"
	case strings.HasSuffix(name, ".tar"), strings.HasSuffix(name, ".tar.gz"), strings.HasSuffix(name, ".tgz"),
		strings.HasSuffix(name, ".tar.xz"), strings.HasSuffix(name, ".txz"), strings.HasSuffix(name, ".tar.bz2"), strings.HasSuffix(name, ".tbz2"):
		return "tar"
	default:
		return ""
	}
}

func ensureTar() error {
	if _, err := exec.LookPath("tar"); err != nil {
		return fmt.Errorf("未找到 tar，请确认运行环境已安装 tar")
	}
	return nil
}

func archiveBaseName(path string) string {
	name := filepath.Base(path)
	lower := strings.ToLower(name)
	for _, suffix := range []string{".tar.gz", ".tar.xz", ".tar.bz2", ".tgz", ".txz", ".tbz2", ".zip", ".tar"} {
		if strings.HasSuffix(lower, suffix) {
			return sanitizeArchiveName(name[:len(name)-len(suffix)], "archive")
		}
	}
	return sanitizeArchiveName(strings.TrimSuffix(name, filepath.Ext(name)), "archive")
}

func sanitizeArchiveName(name, fallback string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		name = fallback
	}
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", "*", "_", "?", "_", "\"", "_", "<", "_", ">", "_", "|", "_")
	name = replacer.Replace(name)
	name = strings.TrimSpace(name)
	if name == "" {
		return fallback
	}
	return name
}

func flattenEntryName(prefix, entryName string, seen map[string]int) string {
	entryName = strings.ReplaceAll(entryName, "\\", "/")
	entryName = strings.TrimPrefix(entryName, "/")
	entryName = strings.TrimSpace(entryName)
	if entryName == "" {
		entryName = "file"
	}
	parts := strings.Split(entryName, "/")
	for i, part := range parts {
		parts[i] = sanitizeArchiveName(part, "file")
	}
	name := strings.Join(parts, "__")
	if prefix != "" {
		name = prefix + "__" + name
	}
	return uniqueArchiveName(name, seen)
}

func uniqueArchiveName(name string, seen map[string]int) string {
	if seen == nil {
		return name
	}
	if _, ok := seen[name]; !ok {
		seen[name] = 1
		return name
	}
	base := strings.TrimSuffix(name, filepath.Ext(name))
	ext := filepath.Ext(name)
	for {
		seen[name]++
		candidate := fmt.Sprintf("%s_%d%s", base, seen[name], ext)
		if _, ok := seen[candidate]; !ok {
			seen[candidate] = 1
			return candidate
		}
	}
}

func listZipEntries(path string, maxEntries int) ([]string, int, error) {
	reader, err := zip.OpenReader(path)
	if err != nil {
		return nil, 0, err
	}
	defer reader.Close()
	total := 0
	var lines []string
	for _, entry := range reader.File {
		if entry.FileInfo().IsDir() {
			continue
		}
		total++
		if maxEntries <= 0 || len(lines) < maxEntries {
			lines = append(lines, fmt.Sprintf("%10d  %s", entry.UncompressedSize64, entry.Name))
		}
	}
	return lines, total, nil
}

func listTarEntries(path string, maxEntries int) ([]string, int, error) {
	if err := ensureTar(); err != nil {
		return nil, 0, err
	}
	out, err := exec.Command("tar", "-tf", path).CombinedOutput()
	if err != nil {
		return nil, 0, fmt.Errorf("tar 查看失败: %v\n%s", err, strings.TrimSpace(string(out)))
	}
	rawLines := strings.Split(strings.TrimSpace(string(out)), "\n")
	var lines []string
	total := 0
	for _, line := range rawLines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasSuffix(line, "/") {
			continue
		}
		total++
		if maxEntries <= 0 || len(lines) < maxEntries {
			lines = append(lines, line)
		}
	}
	return lines, total, nil
}

func copyRegularFile(src, dst string) error {
	input, err := os.Open(src)
	if err != nil {
		return err
	}
	defer input.Close()
	if err := os.MkdirAll(filepath.Dir(dst), 0755); err != nil {
		return err
	}
	output, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer output.Close()
	_, err = io.Copy(output, input)
	return err
}

package archive

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type ListArchiveReq struct {
	InputFiles   string `json:"input_files" widget:"name:上传压缩包;type:files;accept:.zip,.tar,.tgz,.tar.gz,.tar.xz,.txz,.tar.bz2,.tbz2,application/zip,application/x-tar,*/*;max_size:2000MB;max_count:20" validate:"required"`
	MaxEntries   int    `json:"max_entries" widget:"name:最多预览条目;type:number;min:0;max:5000;render_default:300;placeholder:0 表示不限制" validate:"min=0,max=5000"`
	OutputReport bool   `json:"output_report" widget:"name:输出目录清单文件;type:switch;render_default:true"`
}

type ListArchiveResp struct {
	EntriesText string `json:"entries_text" widget:"name:压缩包内容;type:text_area"`
	OutputFile  string `json:"output_file" widget:"name:目录清单;type:files"`
	Summary     string `json:"summary" widget:"name:处理说明;type:text_area"`
}

func ListArchive(ctx *app.Context, resp response.Response) error {
	var req ListArchiveReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoListArchive(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

func DoListArchive(ctx *app.Context, req *ListArchiveReq) (*ListArchiveResp, error) {
	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)
	if len(inputFiles) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	maxEntries := req.MaxEntries
	if maxEntries < 0 {
		maxEntries = 300
	}

	var blocks []string
	var summaries []string
	for _, path := range inputFiles {
		if path == "" {
			continue
		}
		kind := archiveKind(path)
		var entries []string
		var total int
		var err error
		switch kind {
		case "zip":
			entries, total, err = listZipEntries(path, maxEntries)
		case "tar":
			entries, total, err = listTarEntries(path, maxEntries)
		default:
			err = fmt.Errorf("暂不支持该压缩包格式")
		}
		if err != nil {
			summaries = append(summaries, fmt.Sprintf("失败 %s: %v", filepath.Base(path), err))
			continue
		}
		text := strings.Join(entries, "\n")
		if maxEntries > 0 && total > len(entries) {
			text += fmt.Sprintf("\n... 还有 %d 个条目未显示", total-len(entries))
		}
		blocks = append(blocks, fmt.Sprintf("## %s\n格式: %s\n文件条目数: %d\n\n%s", filepath.Base(path), kind, total, text))
		summaries = append(summaries, fmt.Sprintf("成功 %s: %d 个文件条目", filepath.Base(path), total))
	}
	if len(blocks) == 0 {
		return nil, fmt.Errorf("没有成功读取的压缩包\n%s", strings.Join(summaries, "\n"))
	}

	content := strings.TrimSpace(strings.Join(blocks, "\n\n"))
	var outputFile string
	if req.OutputReport {
		outputPath := filepath.Join(fs.GetTraceOutputDir(), "archive_entries.txt")
		if err := os.WriteFile(outputPath, []byte(content), 0644); err != nil {
			return nil, fmt.Errorf("写入目录清单失败: %w", err)
		}
		outputFile = fs.ResponseFiles([]string{outputPath})
	}
	return &ListArchiveResp{
		EntriesText: content,
		OutputFile:  outputFile,
		Summary:     "压缩包目录读取完成\n" + strings.Join(summaries, "\n"),
	}, nil
}

var ListArchiveTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "查看压缩包内容",
		Desc:     `读取 ZIP、TAR、TAR.GZ、TGZ、TAR.XZ 等压缩包目录，不解压即可预览内部文件列表，并可输出目录清单文本。`,
		Tags:     []string{"压缩包", "ZIP", "TAR", "目录清单", "预览"},
		Request:  &ListArchiveReq{},
		Response: &ListArchiveResp{},
	},
}

func init() {
	packageContext.POST("list.form", ListArchive, ListArchiveTemplate)
}

package audio

import (
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/pkg/logger"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type AudioInfoReq struct {
	InputFiles string `json:"input_files" widget:"name:上传音频或视频文件;type:files;accept:audio/*,video/*,*/*;max_size:1000MB;max_count:20" validate:"required"`
	OutputMode string `json:"output_mode" widget:"name:输出模式;type:select;options:摘要,JSON;options_colors:409EFF,67C23A;render_default:摘要" validate:"required,oneof=摘要 JSON"`
}

type AudioInfoResp struct {
	InfoText string `json:"info_text" widget:"name:音频信息;type:text_area"`
	Summary  string `json:"summary" widget:"name:处理说明;type:text_area"`
}

func AudioInfo(ctx *app.Context, resp response.Response) error {
	var req AudioInfoReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoAudioInfo(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

func DoAudioInfo(ctx *app.Context, req *AudioInfoReq) (*AudioInfoResp, error) {
	if err := ensureFFprobe(); err != nil {
		return nil, err
	}

	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)

	files := inputFiles
	if len(files) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	var blocks []string
	var summary []string
	for _, file := range files {
		if file == "" {
			logger.Warnf(ctx, "[Audio/AudioInfo] 文件 %s 无本地路径，跳过", filepath.Base(file))
			summary = append(summary, fmt.Sprintf("跳过 %s: 无本地路径", filepath.Base(file)))
			continue
		}

		args := []string{
			"-v", "error",
			"-select_streams", "a",
			"-show_entries", "stream=index,codec_name,codec_type,sample_rate,channels,channel_layout,bit_rate,duration:format=format_name,duration,size,bit_rate",
		}
		if req.OutputMode == "JSON" {
			args = append(args, "-of", "json")
		} else {
			args = append(args, "-of", "default=noprint_wrappers=1")
		}
		args = append(args, file)
		out, err := exec.Command("ffprobe", args...).CombinedOutput()
		if err != nil {
			logger.Errorf(ctx, "[Audio/AudioInfo] 读取失败 %s: %v, output: %s", filepath.Base(file), err, string(out))
			summary = append(summary, fmt.Sprintf("失败 %s: %v\n%s", filepath.Base(file), err, strings.TrimSpace(string(out))))
			continue
		}

		text := strings.TrimSpace(string(out))
		if text == "" {
			text = "未发现音频流"
		}
		blocks = append(blocks, fmt.Sprintf("## %s\n%s", filepath.Base(file), text))
		summary = append(summary, fmt.Sprintf("成功 %s", filepath.Base(file)))
	}

	if len(blocks) == 0 {
		return nil, fmt.Errorf("没有成功读取的音频信息\n%s", strings.Join(summary, "\n"))
	}
	return &AudioInfoResp{
		InfoText: strings.Join(blocks, "\n\n"),
		Summary:  strings.Join(summary, "\n"),
	}, nil
}

