// sanitizeFileName 清理文件名，移除非法字符
func sanitizeFileName(name string) string {
	if name == "" {
		return ""
	}

	// 替换非法字符为下划线
	illegalChars := []string{"/", "\\", ":", "*", "?", "\"", "<", ">", "|"}
	result := name
	for _, char := range illegalChars {
		result = strings.ReplaceAll(result, char, "_")
	}

	// 移除首尾空格
	result = strings.TrimSpace(result)

	// 如果清理后为空，返回默认值
	if result == "" {
		return "数据图表"
	}

	return result
}

