	BaseConfig: app.BaseConfig{
		Name:     "查看 SQLite 结构",
		Desc:     `读取 SQLite 数据库中的表、视图、索引、触发器定义，并可统计每张表行数。适合查询前快速了解上传 .db 文件结构。`,
		Tags:     []string{"SQLite", "Schema", "数据库结构", "表", "行数"},
		Request:  &InspectReq{},
		Response: &InspectResp{},
	},
}

