import (
	"bytes"
	"encoding/base64"
	"fmt"
	"html/template"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/types"
	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/extension"
	"github.com/yuin/goldmark/parser"
	goldmarkhtml "github.com/yuin/goldmark/renderer/html"
)

func writeHTMLFile(ctx *app.Context, fileName string, content string) (string, string, error) {
	baseName := sanitizeFileName(fileName)
	fs := ctx.GetFS()
	outputDir := fs.GetTraceOutputDir()
	if err := os.MkdirAll(outputDir, 0755); err != nil {
		return "", "", fmt.Errorf("创建输出目录失败: %v", err)
	}

	outputPath := filepath.Join(outputDir, baseName+".html")
	if err := os.WriteFile(outputPath, []byte(content), 0644); err != nil {
		return "", "", fmt.Errorf("保存文件失败: %v", err)
	}
	return fs.ResponseFiles([]string{outputPath}), outputPath, nil
}

func markdownToHTMLFragment(markdownText string) (string, error) {
	md := goldmark.New(
		goldmark.WithExtensions(extension.GFM, extension.Linkify),
		goldmark.WithParserOptions(parser.WithAutoHeadingID()),
		goldmark.WithRendererOptions(goldmarkhtml.WithXHTML()),
	)
	var buf bytes.Buffer
	if err := md.Convert([]byte(markdownText), &buf); err != nil {
		return "", fmt.Errorf("Markdown 渲染失败: %w", err)
	}
	return buf.String(), nil
}

func downloadAssetDataURIs(ctx *app.Context, assets string) ([]string, map[string]string, error) {
	if len(types.ParseFileRefs(assets)) == 0 {
		return nil, nil, nil
	}

	fs := ctx.GetFS()
	downloaded := fs.DownloadFiles(assets)
	dataURIs := make(map[string]string)
	for _, file := range downloaded {
		if file == "" {
			continue
		}
		data, err := os.ReadFile(file)
		if err != nil {
			return downloaded, nil, fmt.Errorf("读取资源文件 %s 失败: %v", filepath.Base(file), err)
		}
		name := strings.TrimSpace(filepath.Base(file))
		if name == "" {
			name = filepath.Base(file)
		}
		mimeType := mime.TypeByExtension(filepath.Ext(name))
		if mimeType == "" {
			mimeType = http.DetectContentType(data)
		}
		dataURI := "data:" + mimeType + ";base64," + base64.StdEncoding.EncodeToString(data)
		addAssetKeys(dataURIs, dataURI, name, filepath.Base(name))
	}
	return downloaded, dataURIs, nil
}

func addAssetKeys(dataURIs map[string]string, dataURI string, keys ...string) {
	for _, key := range keys {
		key = strings.TrimSpace(key)
		if key == "" {
			continue
		}
		dataURIs[key] = dataURI
		dataURIs[filepath.Base(key)] = dataURI
	}
}

func embedAssetPlaceholders(content string, dataURIs map[string]string) (string, int) {
	if len(dataURIs) == 0 || content == "" {
		return content, 0
	}
	used := 0
	for name, dataURI := range dataURIs {
		placeholder := "{{asset:" + name + "}}"
		count := strings.Count(content, placeholder)
		if count == 0 {
			continue
		}
		content = strings.ReplaceAll(content, placeholder, dataURI)
		used += count
	}
	return content, used
}

func assetUsageInfo(totalAssets int, usedPlaceholders int) string {
	if totalAssets == 0 {
		return ""
	}
	return fmt.Sprintf("\n资源文件: %d 个\n已替换资源占位符: %d 个\n占位符格式: {{asset:文件名}}，例如 <img src=\"{{asset:logo.png}}\">", totalAssets, usedPlaceholders)
}

func assetFileCount(assets string) int {
	return len(types.ParseFileRefs(assets))
}

func htmlPageShell(title string, body string, style string) string {
	return fmt.Sprintf(`<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>%s</title>
<style>
%s
</style>
</head>
<body>
%s
</body>
</html>`, template.HTMLEscapeString(title), style, body)
}

package html

import (
	"fmt"
	"html/template"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type HTMLGenerateReq struct {
	HTMLCode string `json:"html_code" widget:"name:HTML 代码;type:text_area;placeholder:输入完整的 HTML 代码（包含 html/head/body），或只输入 body 内容" validate:"required"`
	FileName string `json:"file_name" widget:"name:文件名;type:input;placeholder:输入文件名（无需后缀），例如 my-page" validate:"required"`
	WrapPage string `json:"wrap_page" widget:"name:自动包装;type:select;options:自动检测,强制包装完整页面,不包装直接输出;render_default:自动检测" validate:"required"`
	Title    string `json:"page_title" widget:"name:页面标题;type:input;placeholder:可选，仅包装模式有效"`
	Assets   string `json:"assets" widget:"name:页面资源;type:files;accept:image/*,.svg,.webp,.png,.jpg,.jpeg,.gif;max_size:20MB;max_count:30"`
}

type HTMLGenerateResp struct {
	OutputFile string `json:"output_file" widget:"name:HTML 文件;type:files"`
	Info       string `json:"info" widget:"name:生成信息;type:text_area"`
}

func HTMLGenerate(ctx *app.Context, resp response.Response) error {
	var req HTMLGenerateReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}

	baseName := sanitizeFileName(req.FileName)

	code := req.HTMLCode
	needsWrap := false

	switch req.WrapPage {
	case "强制包装完整页面":
		needsWrap = true
	case "不包装直接输出":
		needsWrap = false
	default:
		needsWrap = !looksLikeFullPage(code)
	}

	if needsWrap {
		title := req.Title
		if title == "" {
			title = baseName
		}
		code = wrapHTMLPage(title, code)
	}

	fs := ctx.GetFS()
	downloadedAssets, assetURIs, err := downloadAssetDataURIs(ctx, req.Assets)
	if err != nil {
		return err
	}
	defer fs.RemoveFiles(downloadedAssets)
	code, usedAssets := embedAssetPlaceholders(code, assetURIs)

	outputFiles, _, err := writeHTMLFile(ctx, baseName, code)
	if err != nil {
		return err
	}

	info := fmt.Sprintf("文件: %s.html\n大小: %d 字符", baseName, len(code))
	if needsWrap {
		info += "\n已自动包装为完整 HTML 页面"
	}
	info += assetUsageInfo(assetFileCount(req.Assets), usedAssets)

	return resp.Form(&HTMLGenerateResp{
		OutputFile: outputFiles,
		Info:       info,
	}).Build()
}

func looksLikeFullPage(code string) bool {
	lower := strings.ToLower(strings.TrimSpace(code))
	return strings.HasPrefix(lower, "<!doctype") || strings.HasPrefix(lower, "<html")
}

func wrapHTMLPage(title, body string) string {
	return fmt.Sprintf(`<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>%s</title>
<style>
* { box-sizing: border-box; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Noto Sans SC", sans-serif; margin: 0; padding: 2rem; line-height: 1.6; color: #333; background: #fff; }
</style>
</head>
<body>
%s
</body>
</html>`, template.HTMLEscapeString(title), body)
}

func sanitizeFileName(name string) string {
	name = strings.TrimSpace(name)
	name = strings.TrimSuffix(name, ".html")
	name = strings.TrimSuffix(name, ".HTML")
	name = strings.TrimSuffix(name, ".htm")
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", "*", "_", "?", "_", "\"", "_", "<", "_", ">", "_", "|", "_")
	name = replacer.Replace(name)
	if strings.TrimSpace(name) == "" {
		name = "page"
	}
	runes := []rune(name)
	if len(runes) > 200 {
		name = string(runes[:200])
	}
	return name
}

var HTMLGenerateTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "HTML 页面生成",
		Desc:     `将 HTML 代码生成为可直接访问的网页文件。输入完整 HTML 或片段代码，自动检测并包装为完整页面。支持上传图片资源，并在 HTML 中用 {{asset:文件名}} 占位符内嵌为 data URI。常用于快速生成活动页、展示页、工具页等场景。`,
		Tags:     []string{"HTML", "网页", "页面生成", "HTML生成", "前端", "网页制作", "资源内嵌"},
		Request:  &HTMLGenerateReq{},
		Response: &HTMLGenerateResp{},
	},
}

func init() {
	packageContext.POST("html_generate.form", HTMLGenerate, HTMLGenerateTemplate)
}

