mermaid.initialize({ startOnLoad: true, theme: '%s', securityLevel: 'loose' });
</script>
</body>
</html>`,
		template.HTMLEscapeString(pageTitle),
		mermaidBgColor(theme),
		mermaidTitleColor(theme),
		mermaidCardBg(theme),
		titleHTML,
		template.HTMLEscapeString(mermaidCode),
		theme,
	)
}

