	BaseConfig: app.BaseConfig{
		Name:     "PNG 图片压缩",
		Desc:     `使用 pngquant 压缩 PNG 图片，可设置质量范围。适合网页 PNG、截图、透明图标等文件体积优化。`,
		Tags:     []string{"图片", "PNG", "压缩", "pngquant", "图片优化"},
		Request:  &CompressPNGReq{},
		Response: &CompressPNGResp{},
	},
}

