	}
	if len(blocks) == 0 {
		return nil, fmt.Errorf("没有成功读取的 PDF 信息\n%s", strings.Join(summary, "\n"))
	}
	return &PDFInfoResp{
		InfoText: strings.Join(blocks, "\n\n"),
