)

// ExcelToMarkdownReq Excel 转 Markdown 请求
type ExcelToMarkdownReq struct {
	InputFiles string `json:"input_files" widget:"name:上传Excel文件;type:files;accept:.xlsx,.xls;max_size:50MB;max_count:10" validate:"required"`
	SheetName  string `json:"sheet_name" widget:"name:指定工作表(可选);type:input;placeholder:留空则输出所有工作表"`
}

// ExcelToMarkdownResp Excel 转 Markdown 响应
type ExcelToMarkdownResp struct {
	MarkdownText string `json:"markdown_text" widget:"name:Markdown表格;type:text_area"`
	Summary      string `json:"summary" widget:"name:说明;type:text_area"`
}

// ExcelToMarkdown 入口
func ExcelToMarkdown(ctx *app.Context, resp response.Response) error {
	var req ExcelToMarkdownReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoExcelToMarkdown(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

// DoExcelToMarkdown 读取 xlsx 所有（或指定）工作表，输出为 Markdown 表格文本
func DoExcelToMarkdown(ctx *app.Context, req *ExcelToMarkdownReq) (*ExcelToMarkdownResp, error) {
	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)

	files := inputFiles
	if len(files) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	wantSheet := strings.TrimSpace(req.SheetName)
	var outParts []string
	var summaryParts []string

	for _, file := range files {
		if file == "" {
			logger.Warnf(ctx, "[excel/ToMarkdown] 文件 %s 无本地路径，跳过", filepath.Base(file))
			summaryParts = append(summaryParts, fmt.Sprintf("跳过 %s: 无本地路径", filepath.Base(file)))
			continue
		}

		f, err := excelize.OpenFile(file)
		if err != nil {
			logger.Errorf(ctx, "[excel/ToMarkdown] 打开失败 %s: %v", filepath.Base(file), err)
			summaryParts = append(summaryParts, fmt.Sprintf("失败 %s: %v", filepath.Base(file), err))
			continue
		}

		sheetList := f.GetSheetList()
		if len(sheetList) == 0 {
			f.Close()
			summaryParts = append(summaryParts, fmt.Sprintf("跳过 %s: 无工作表", filepath.Base(file)))
			continue
		}

		exportSheets := sheetList
		if wantSheet != "" {
			exportSheets = nil
			for _, s := range sheetList {
				if s == wantSheet {
					exportSheets = []string{s}
					break
				}
			}
			if len(exportSheets) == 0 {
				f.Close()
				summaryParts = append(summaryParts, fmt.Sprintf("跳过 %s: 未找到工作表「%s」", filepath.Base(file), wantSheet))
				continue
			}
		}

		for _, sheetName := range exportSheets {
			rows, err := f.GetRows(sheetName)
			if err != nil {
				summaryParts = append(summaryParts, fmt.Sprintf("  %s / %s 读取失败: %v", filepath.Base(file), sheetName, err))
				continue
			}
			md := rowsToMarkdownTable(rows)
			if len(exportSheets) > 1 || len(files) > 1 {
				outParts = append(outParts, fmt.Sprintf("### %s — %s\n\n%s", filepath.Base(file), sheetName, md))
			} else {
				outParts = append(outParts, md)
			}
		}
		f.Close()
		summaryParts = append(summaryParts, fmt.Sprintf("已转 %s，%d 个工作表", filepath.Base(file), len(exportSheets)))
	}

	markdownText := strings.TrimSpace(strings.Join(outParts, "\n\n"))
	if markdownText == "" {
		markdownText = "(无数据)"
	}
	return &ExcelToMarkdownResp{
		MarkdownText: markdownText,
		Summary:      strings.Join(summaryParts, "\n"),
	}, nil
}

// rowsToMarkdownTable 将 [][]string 转为 Markdown 表格（首行为表头，第二行为分隔 |---|）
func rowsToMarkdownTable(rows [][]string) string {
	if len(rows) == 0 {
		return ""
	}
	var b strings.Builder
	// 表头
	header := rows[0]
	b.WriteString("| ")
	b.WriteString(strings.Join(escapeMarkdownCells(header), " | "))
	b.WriteString(" |\n")
	// 分隔行
	sep := make([]string, len(header))
	for i := range sep {
		sep[i] = "---"
	}
	b.WriteString("| ")
	b.WriteString(strings.Join(sep, " | "))
	b.WriteString(" |\n")
	// 数据行
	for _, row := range rows[1:] {
		// 补齐列数
		for len(row) < len(header) {
			row = append(row, "")
		}
		if len(row) > len(header) {
			row = row[:len(header)]
		}
		b.WriteString("| ")
		b.WriteString(strings.Join(escapeMarkdownCells(row), " | "))
		b.WriteString(" |\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

// escapeMarkdownCells 对单元格中的 | 和换行做转义，便于 Markdown 表格正确显示
func escapeMarkdownCells(cells []string) []string {
	out := make([]string, len(cells))
	for i, c := range cells {
		c = strings.ReplaceAll(c, "|", "\\|")
		c = strings.ReplaceAll(c, "\n", " ")
		c = strings.TrimSpace(c)
		out[i] = c
	}
	return out
}

var ExcelToMarkdownTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "Excel 转 Markdown 表格",
		Desc:     `上传 xlsx 或 xls，将所有工作表转为 Markdown 表格文本（首行为表头）。可指定单个工作表，不指定则输出全部。适合写文档、放 README、或给大模型做结构化输入。`,
		Tags:     []string{"Excel", "xlsx", "xls", "Markdown", "Excel转Markdown", "excel转markdown", "表格转Markdown", "多工作表", "写文档", "README"},
		Request:  &ExcelToMarkdownReq{},
		Response: &ExcelToMarkdownResp{},
	},
}

func init() {
	packageContext.POST("excel_to_markdown.form", ExcelToMarkdown, ExcelToMarkdownTemplate)
}

package table

import (
	stdcsv "encoding/csv"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

func delimiterRune(option string, sample []byte) rune {
	switch strings.TrimSpace(option) {
	case "制表符":
		return '\t'
	case "分号":
		return ';'
	case "竖线":
		return '|'
	case "逗号":
		return ','
	default:
		return detectDelimiter(sample)
	}
}

func detectDelimiter(sample []byte) rune {
	candidates := []rune{',', '\t', ';', '|'}
	best := ','
	bestScore := -1
	lines := strings.Split(string(sample), "\n")
	if len(lines) > 20 {
		lines = lines[:20]
	}
	for _, candidate := range candidates {
		score := 0
		nonZero := 0
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" {
				continue
			}
			count := strings.Count(line, string(candidate))
			if count > 0 {
				nonZero++
				score += count
			}
		}
		score += nonZero * 10
		if score > bestScore {
			best = candidate
			bestScore = score
		}
	}
	return best
}

func newCSVReader(path string, delimiter rune) (*stdcsv.Reader, *os.File, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	reader := stdcsv.NewReader(file)
	reader.Comma = delimiter
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = true
	reader.TrimLeadingSpace = true
	return reader, file, nil
}

func readSample(path string, max int) []byte {
	if max <= 0 {
		max = 65536
	}
	file, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer file.Close()
	buf := make([]byte, max)
	n, _ := file.Read(buf)
	return buf[:n]
}

func normalizeRecord(record []string) []string {
	out := make([]string, len(record))
	for i, cell := range record {
		if i == 0 {
			cell = strings.TrimPrefix(cell, "\ufeff")
		}
		out[i] = strings.TrimSpace(cell)
	}
	return out
}

func readCSVRows(path string, delimiter rune, maxRows int) ([][]string, bool, error) {
	reader, file, err := newCSVReader(path, delimiter)
	if err != nil {
		return nil, false, err
	}
	defer file.Close()
	var rows [][]string
	truncated := false
	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return rows, truncated, err
		}
		if maxRows > 0 && len(rows) >= maxRows {
			truncated = true
			break
		}
		rows = append(rows, normalizeRecord(record))
	}
	return rows, truncated, nil
}

func csvOutputName(inputName, customName, suffix, ext string, single bool) string {
	if single && strings.TrimSpace(customName) != "" {
		return csvEnsureExt(customName, ext)
	}
	base := csvSafeBase(inputName, "data")
	return base + suffix + "." + strings.TrimPrefix(ext, ".")
}

func csvSafeBase(name, fallback string) string {
	name = strings.TrimSuffix(filepath.Base(strings.TrimSpace(name)), filepath.Ext(name))
	if name == "" {
		name = fallback
	}
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", "*", "_", "?", "_", "\"", "_", "<", "_", ">", "_", "|", "_")
	name = replacer.Replace(name)
	name = strings.TrimSpace(name)
	if name == "" {
		return fallback
	}
	return name
}

func csvEnsureExt(name, ext string) string {
	base := csvSafeBase(name, "data")
	return base + "." + strings.TrimPrefix(ext, ".")
}

func delimiterLabel(delimiter rune) string {
	switch delimiter {
	case '\t':
		return "制表符"
	case ';':
		return "分号"
	case '|':
		return "竖线"
	default:
		return "逗号"
	}
}

func markdownTable(headers []string, rows [][]string, maxRows int) string {
	if len(headers) == 0 {
		return ""
	}
	if maxRows <= 0 || maxRows > len(rows) {
		maxRows = len(rows)
	}
	var b strings.Builder
	b.WriteString("| ")
	for _, header := range headers {
		b.WriteString(escapeMarkdownCell(header))
		b.WriteString(" | ")
	}
	b.WriteString("\n| ")
	for range headers {
		b.WriteString("--- | ")
	}
	for i := 0; i < maxRows; i++ {
		b.WriteString("\n| ")
		for col := range headers {
			cell := ""
			if col < len(rows[i]) {
				cell = rows[i][col]
			}
			b.WriteString(escapeMarkdownCell(cell))
			b.WriteString(" | ")
		}
	}
	return b.String()
}

func escapeMarkdownCell(value string) string {
	value = strings.ReplaceAll(value, "|", "\\|")
	value = strings.ReplaceAll(value, "\n", " ")
	value = strings.ReplaceAll(value, "\r", " ")
	if len([]rune(value)) > 80 {
		return string([]rune(value)[:80]) + "..."
	}
	return value
}

func inferCellType(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "empty"
	}
	if _, err := strconv.ParseInt(value, 10, 64); err == nil {
		return "integer"
	}
	if _, err := strconv.ParseFloat(value, 64); err == nil {
		return "float"
	}
	lower := strings.ToLower(value)
	if lower == "true" || lower == "false" || lower == "yes" || lower == "no" {
		return "boolean"
	}
	for _, layout := range []string{"2006-01-02", "2006-01-02 15:04:05", time.RFC3339, "2006/01/02", "01/02/2006"} {
		if _, err := time.Parse(layout, value); err == nil {
			return "date"
		}
	}
	return "text"
}

func mergeCellType(current, next string) string {
	if current == "" || current == "empty" {
		return next
	}
	if next == "" || next == "empty" || current == next {
		return current
	}
	if (current == "integer" && next == "float") || (current == "float" && next == "integer") {
		return "float"
	}
	return "text"
}

func generatedHeaders(width int) []string {
	headers := make([]string, width)
	for i := range headers {
		headers[i] = fmt.Sprintf("column_%d", i+1)
	}
	return headers
}

func normalizeHeaders(row []string) []string {
	seen := map[string]int{}
	headers := make([]string, len(row))
	for i, header := range row {
		header = strings.TrimSpace(header)
		if header == "" {
			header = fmt.Sprintf("column_%d", i+1)
		}
		if seen[header] == 0 {
			seen[header] = 1
			headers[i] = header
			continue
		}
		seen[header]++
		headers[i] = fmt.Sprintf("%s_%d", header, seen[header])
	}
	return headers
}

package table

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type InspectCSVReq struct {
	InputFiles   string `json:"input_files" widget:"name:上传 CSV/TSV 文件;type:files;accept:.csv,.tsv,text/csv,text/tab-separated-values,text/*,*/*;max_size:500MB;max_count:20" validate:"required"`
	Delimiter    string `json:"delimiter" widget:"name:分隔符;type:select;options:自动,逗号,制表符,分号,竖线;options_colors:409EFF,909399,67C23A,E6A23C,909399;render_default:自动" validate:"required,oneof=自动 逗号 制表符 分号 竖线"`
	HasHeader    bool   `json:"has_header" widget:"name:首行是表头;type:switch;render_default:true"`
	MaxRows      int    `json:"max_rows" widget:"name:最多采样行数;type:number;min:10;max:100000;render_default:1000" validate:"min=0,max=100000"`
	OutputReport bool   `json:"output_report" widget:"name:输出体检报告文件;type:switch;render_default:true"`
}

type InspectCSVResp struct {
	ReportText string `json:"report_text" widget:"name:CSV 体检报告;type:text_area"`
	OutputFile string `json:"output_file" widget:"name:体检报告;type:files"`
	Summary    string `json:"summary" widget:"name:处理说明;type:text_area"`
}

func InspectCSV(ctx *app.Context, resp response.Response) error {
	var req InspectCSVReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	res, err := DoInspectCSV(ctx, &req)
	if err != nil {
		return err
	}
	return resp.Form(res).Build()
}

func DoInspectCSV(ctx *app.Context, req *InspectCSVReq) (*InspectCSVResp, error) {
	fs := ctx.GetFS()
	inputFiles := fs.DownloadFiles(req.InputFiles)
	defer fs.RemoveFiles(inputFiles)
	if len(inputFiles) == 0 {
		return nil, fmt.Errorf("没有找到输入文件")
	}

	maxRows := req.MaxRows
	if maxRows <= 0 {
		maxRows = 1000
	}

	var blocks []string
	var summaries []string
	for _, path := range inputFiles {
		if path == "" {
			continue
		}
		block, summary, err := inspectOneCSV(path, req.Delimiter, req.HasHeader, maxRows)
		if err != nil {
			summaries = append(summaries, fmt.Sprintf("失败 %s: %v", filepath.Base(path), err))
			continue
		}
		blocks = append(blocks, block)
		summaries = append(summaries, summary)
	}
	if len(blocks) == 0 {
		return nil, fmt.Errorf("没有成功读取的 CSV 文件\n%s", strings.Join(summaries, "\n"))
	}

	report := strings.TrimSpace(strings.Join(blocks, "\n\n"))
	var outputFile string
	if req.OutputReport {
		outputPath := filepath.Join(fs.GetTraceOutputDir(), "csv_inspection_report.md")
		if err := os.WriteFile(outputPath, []byte(report), 0644); err != nil {
			return nil, fmt.Errorf("写入体检报告失败: %w", err)
		}
		outputFile = fs.ResponseFiles([]string{outputPath})
	}
	return &InspectCSVResp{
		ReportText: report,
		OutputFile: outputFile,
		Summary:    "CSV 体检完成\n" + strings.Join(summaries, "\n"),
	}, nil
}

func inspectOneCSV(path, delimiterOption string, hasHeader bool, maxRows int) (string, string, error) {
	sample := readSample(path, 65536)
	delimiter := delimiterRune(delimiterOption, sample)
	rows, truncated, err := readCSVRows(path, delimiter, maxRows)
	if err != nil {
		return "", "", err
	}
	if len(rows) == 0 {
		return "", "", fmt.Errorf("文件为空或没有可读行")
	}

	headers := rows[0]
	dataRows := rows
	if hasHeader {
		headers = normalizeHeaders(rows[0])
		dataRows = rows[1:]
	} else {
		headers = generatedHeaders(maxRecordWidth(rows))
	}
	types, fillCounts := inferColumns(headers, dataRows)
	stat, _ := os.Stat(path)

	var b strings.Builder
	b.WriteString("## ")
	b.WriteString(filepath.Base(path))
	b.WriteString("\n")
	if stat != nil {
		b.WriteString(fmt.Sprintf("- 文件大小: %d bytes\n", stat.Size()))
	}
	b.WriteString(fmt.Sprintf("- 分隔符: %s\n", delimiterLabel(delimiter)))
	b.WriteString(fmt.Sprintf("- 采样行数: %d\n", len(rows)))
	b.WriteString(fmt.Sprintf("- 数据行数(采样内): %d\n", len(dataRows)))
	b.WriteString(fmt.Sprintf("- 列数: %d\n", len(headers)))
	if truncated {
		b.WriteString("- 注意: 文件行数超过采样上限，报告基于采样数据\n")
	}
	b.WriteString("\n### 字段\n")
	for i, header := range headers {
		fill := 0
		if i < len(fillCounts) {
			fill = fillCounts[i]
		}
		typ := "empty"
		if i < len(types) && types[i] != "" {
			typ = types[i]
		}
		b.WriteString(fmt.Sprintf("- `%s`: %s，非空 %d/%d\n", header, typ, fill, len(dataRows)))
	}
	if len(dataRows) > 0 {
		b.WriteString("\n### 数据预览\n")
		b.WriteString(markdownTable(headers, dataRows, 20))
	}
	return b.String(), fmt.Sprintf("成功 %s: %d 列，采样 %d 行", filepath.Base(path), len(headers), len(rows)), nil
}

func maxRecordWidth(rows [][]string) int {
	width := 0
	for _, row := range rows {
		if len(row) > width {
			width = len(row)
		}
	}
	return width
}

func inferColumns(headers []string, rows [][]string) ([]string, []int) {
	types := make([]string, len(headers))
	fillCounts := make([]int, len(headers))
	for _, row := range rows {
		for i := range headers {
			value := ""
			if i < len(row) {
				value = row[i]
			}
			if strings.TrimSpace(value) != "" {
				fillCounts[i]++
			}
			types[i] = mergeCellType(types[i], inferCellType(value))
		}
	}
	return types, fillCounts
}

