// VideoConvertResp 视频格式转换响应结构体
type VideoConvertResp struct {
	// 转换后的视频文件
	OutputFile string `json:"output_file" widget:"name:转换后的视频;type:files"`

	// 转换信息
	ConvertInfo string `json:"convert_info" widget:"name:转换信息;type:text_area"`

